return ['domain'=>'tag-groups','plural-forms'=>'nplurals=1; plural=0;','language'=>'yor','project-id-version'=>'Tag Groups 2.1.2','pot-creation-date'=>'2026-06-15T12:41:40+00:00','po-revision-date'=>'2026-06-17 15:08+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['Tag Groups'=>'Tag-Groups','https://wordpress.org/plugins/tag-groups/'=>'https://wordpress.org/plugins/tag-groups/','Tag Groups allows you to organize your WordPress taxonomy terms and show them in clouds, tabs, accordions, tables, lists and much more.'=>'Tag-Groups ngbanilaaye fun ọ lati ṣeto awọn ọrọ taxonomy WordPress rẹ ki o si fi wọn han ni awọn awọ, awọn taabu, awọn akordeon, awọn tabili, awọn atokọ ati pupọ diẹ sii.','TaxoPress'=>'TaxoPress','https://taxopress.com'=>'https://taxopress.com','Home'=>'Ile','Taxonomies'=>'Taxonomies','Front End'=>'Iwaju','Back End'=>'Ẹyin','First Steps'=>'Igbese akọkọ','Setup Wizard'=>'Oludasilẹ Eto','Settings'=>'Awọn eto','Tag Group Admin'=>'Oludari Ẹgbẹ Tag','The term has been removed from all groups.'=>'Ọrọ naa ti yọ kuro ninu gbogbo awọn ẹgbẹ.','Edit this item inline'=>'Ṣatunkọ nkan yii lẹsẹkẹsẹ','Quick&nbsp;Edit'=>'Yara&nbsp;Ṣatunkọ','Please <a %s>click here to run the migration routines</a> to make sure we have migrated all tags.'=>'Jọwọ <a %s>tẹ nibi lati ṣiṣẹ awọn ilana gbigbe</a> lati rii daju pe a ti gbe gbogbo awọn afi.','Your settings/groups and your terms have been exported. Please download the resulting files with right-click or ctrl-click:'=>'Awọn eto/awọn ẹgbẹ rẹ ati awọn ọrọ rẹ ti wa ni gbejade. Jọwọ gba awọn faili ti o ṣẹda pẹlu tite-ọtun tabi ctrl-tite:','Writing of the exported settings failed.'=>'Kikọ ti awọn eto ti a gbejade kuna.','The groups have been sorted alphabetically.'=>'Awọn ẹgbẹ ti wa ni ṣeto ni aṣẹ alfabeti.','The label cannot be empty.'=>'Aami naa ko le jẹ ofo.','A tag group with the label \'%s\' already exists, or the label has not changed. Please choose another one or go back.'=>'A ẹgbẹ aami pẹlu aami \'%s\' ti wa tẹlẹ, tabi aami naa ko ti yipada. Jọwọ yan miiran tabi pada sẹhin.','A new tag group with the label \'%s\' has been created!'=>'A ẹgbẹ aami tuntun pẹlu aami \'%s\' ti ṣẹda!','A tag group with the label \'%s\' already exists.'=>'A ẹgbẹ aami pẹlu aami \'%s\' ti wa tẹlẹ.','The tag group with the label \'%s\' has been saved!'=>'A ẹgbẹ aami pẹlu aami \'%s\' ti fipamọ!','A tag group with the id %1$s and the label \'%2$s\' has been deleted.'=>'A ẹgbẹ aami pẹlu id %1$s ati aami \'%2$s\' ti paarẹ.','Error uploading the file.'=>'Aṣiṣe n\'ikojọpọ faili naa.','Error reading the file.'=>'Aṣiṣe n\'ka faili naa.','Error parsing the file.'=>'Aṣiṣe n\'ṣe itumọ faili naa.','date unknown'=>' ọjọ ti ko mọ ','Your settings and groups have been imported from the file %1$s (created with plugin version %2$s on %3$s).'=>'Awọn eto rẹ ati awọn ẹgbẹ ti wa ni gbe wọle lati faili %1$s (ti a ṣẹda pẹlu ẹya plugin %2$s ni %3$s).','%d option was added or changed.'=>'%d aṣayan ni a fi kun tabi yipada.','Your terms have been imported from the file %1$s (created with plugin version %2$s on %3$s).'=>'Awọn ofin rẹ ti wa ni gbe wọle lati faili %1$s (ti a ṣẹda pẹlu ẹya plugin %2$s ni %3$s).','We processed %d term.'=>'A ṣe ilana %d ofin.','We saved %d term.'=>'A fipamọ %d ofin.','The group info of %d term was updated.'=>'Alaye ẹgbẹ ti %d ofin ti ni imudojuiwọn.','Filters'=>'Awọn asẹ','Gutenberg'=>'Gutenberg','Multilingual'=>'Pupọ èdè','Shortcodes'=>'Koodu kukuru','Themes and Appearance'=>'Àwọn akọlé àti Ìfarahàn','remove'=>'yọ','(recommended)'=>'(ti a ṣedasilẹ)','keep'=>'tẹsiwaju','use unfiltered_html filter'=>'lo unfiltered_html àlẹmọ','First Aid'=>'Iranwọ́ Àkọ́kọ́','REST API'=>'REST API','System Information'=>'Alaye Eto','Debugging'=>'Ìtẹ́wọ́gbà','Export/Import'=>'Gbigbe/Ìwọle','Reset'=>'Tunṣe','Licences'=>'Ìwé-aṣẹ','Transients'=>'Àkópọ̀','Database'=>'Àkóso data','Filesystem'=>'Fáìlìsìtẹ́mù','WP Object Cache'=>'WP Objekti Cache','Your settings have been saved.'=>'Àwọn ìtọ́sọ́nà rẹ ti fipamọ́.','Your settings has been saved.'=>'Àwọn ìtọ́sọ́nà rẹ ti fipamọ́.','All groups have been deleted and assignments reset.'=>'Gbogbo ẹgbẹ́ ti parẹ́ ati ìtẹ́wọn jẹ́ tuntun.','The filter on the tags page has been reset to show all tags.'=>'Àlẹmọ lori oju-iwe awọn afi ti wa ni tunto lati fihan gbogbo awọn afi.','tag groups'=>' ẹgbẹ awọn aami ','tag cloud'=>' awọ aami ','group info'=>' alaye ẹgbẹ ','sidebar widget'=>' widget ẹgbẹ ẹgbẹ ','accordion'=>' accordion ','tabs'=>' awọn taabu ','alphabetical'=>' lẹta akọkọ ','post list'=>' atokọ ifiweranṣẹ ','colors'=>' awọn awọ ','tag description'=>' apejuwe aami ','tag filter'=>' àlẹmọ aami ','post filter'=>' àlẹmọ ifiweranṣẹ ','backup'=>' afẹyinti ','remove plugin'=>' yọ plugin ','remove data'=>' yọ data ','delete groups'=>' pa awọn ẹgbẹ ','debugging'=>' itupalẹ aṣiṣe ','PHP Version'=>' PHP Version ','Ajax Test'=>' Ajax Idanwo ','troubleshooting'=>' iṣoro iṣeduro ','benchmarks'=>'ìdánwò','speed test'=>'ìdánwò iyara','error'=>'àṣìṣe','testing'=>'ìdánwò','help'=>'ìrànlọ́wọ́','Tag Groups Pro'=>'Ẹgbẹ́ Àmúyẹ Tag','upgrade'=>'ìmúṣẹ','more groups'=>'pọ̀ si i ẹgbẹ́','posts'=>'àwọn ìpòṣítì','filter'=>'fìlítà','animated'=>'ṣíṣe àfihàn','searchable'=>'àmúyẹ','Info'=>'Alaye','author'=>'onkọ́wé','version'=>'ẹ̀dá','contact'=>'kan si','about'=>'nípa','Licenses'=>'Ìwé-aṣẹ','Credits'=>'Kíkọ́','Development News'=>'Ìròyìn Ìdàgbàsókè','blog'=>'blog','updates'=>'imudojuiwọn','getting started'=>'bẹrẹ','introduction'=>'introduction','sample'=>'apẹẹrẹ','migrate'=>'yiyipada','problem'=>'isoro','live block preview'=>'awotẹlẹ bulọọki laaye','translation'=>'itumo','Migrating the term meta'=>'Yiyipada ọrọ meta','Fixing incorrect tag groups'=>'Ṣiṣe atunṣe awọn ẹgbẹ tag ti ko tọ','Fixing incorrect groups in term meta'=>'Ṣiṣe atunṣe awọn ẹgbẹ ti ko tọ ninu ọrọ meta','Sorting groups in term meta'=>'Ṣiṣe ìtòsọ́tọ̀ àwọn ẹgbẹ́ nínú ọrọ meta','Checking the tag names'=>'Ṣayẹwo awọn orukọ tag','Start'=>'Bẹrẹ','Sample Content'=>'Akopọ Apẹẹrẹ','Sample Group A'=>'Ẹgbẹ Apẹẹrẹ A','Sample Group B'=>'Ẹgbẹ Apẹẹrẹ B','Sample Group C'=>'Ẹgbẹ Apẹẹrẹ C','First Sample Tag'=>'Tag Apẹẹrẹ akọkọ','Second Sample Tag'=>'Apẹẹrẹ Tag Keji','Third Sample Tag'=>'Apẹẹrẹ Tag Kẹta','Create a draft sample page with Gutenberg blocks.'=>'Ṣẹda oju-iwe apẹẹrẹ àtẹjáde pẹlu awọn bulọọki Gutenberg.','Create a draft sample page with shortcodes.'=>'Ṣẹda oju-iwe apẹẹrẹ àtẹjáde pẹlu awọn koodu kukuru.','The plugin %1$s requires WordPress %2$s to function properly.'=>'Plugin %1$s nilo WordPress %2$s lati ṣiṣẹ daradara.','Please upgrade WordPress and then try again.'=>'Jọwọ ṣe imudojuiwọn WordPress ki o si gbiyanju lẹẹkansi.','not assigned'=>'kii ṣe atunto','You\'re using Tag Groups Free. The Pro version has more features and support. %1$sUpgrade to Pro%2$s'=>'Iwọ nlo Tag Groups Free. Ẹya Pro ni awọn ẹya diẹ sii ati atilẹyin. %1$sṢe igbesoke si Pro%2$s','Upgrade to Pro'=>'Ṣe imudojuiwọn si Pro','Upgrade to Tag Groups Pro'=>'Ṣe imudojuiwọn si Tag Groups Pro','Enhance the power of Tag Groups with the Pro version:'=>'Mu agbara Tag Groups pọ si pẹlu ẹya Pro:','21 Shortcodes'=>'21 Awọn koodu kukuru','18 Gutenberg Blocks'=>'18 Awọn bulọọki Gutenberg','Table Tag Cloud'=>'Awọ Tag Tabili','Simple Tag Cloud'=>'Awọ Tag Ti o rọrun','Shuffle Box'=>'Apoti Shuffle','Caching'=>'Caching','Multiple Groups Per Tag'=>'Awọn ẹgbẹ Ọpọlọpọ fun Tag Kọọkan','Tag Cloud Search'=>'Ìwádìí Awọ Tag','Toggle Post Filter'=>'Yipada Ẹrọ àlẹmọ Post','Dynamic Post Filter'=>'Ifilteri Post Alagbara','Post List'=>'Atokọ Post','Tag Meta Box'=>'Ibo Meta Tag','Post Tags in Groups'=>'Awọn Tag Post ninu Awọn Ẹgbẹ','Permissions'=>'Awọn igbanilaaye','Default Groups'=>'Awọn Ẹgbẹ Aiyipada','WooCommerce Attributes'=>'Awọn ohun-ini WooCommerce','Parent Group Level'=>'Ipele Ẹgbẹ Abáni','Need Tag Groups Support?'=>'Njẹ o nilo Atilẹyin Ẹgbẹ Tag?','If you need help or have a new feature request, let us know.'=>'Ti o ba nilo iranlọwọ tabi ni ibeere ẹya tuntun, jẹ ki a mọ.','Request Support'=>'Beere Atilẹyin','Detailed documentation is also available on the plugin website.'=>'Iwe aṣẹ alaye ti wa ni ipese lori oju opo wẹẹbu plugin.','View Knowledge Base'=>'Wo Ibi Ẹkọ','The free Tag Groups plugin cannot be active together with Tag Groups Pro.'=>'Plugin Ẹgbẹ Tag ọfẹ ko le ṣiṣẹ papọ pẹlu Tag Groups Pro.','more information'=>'alaye diẹ sii','Edit tag groups'=>'Ṣatunkọ awọn ẹgbẹ tag','Clicking will leave this page without saving.'=>'Tite yoo fi oju-iwe yii silẹ laisi fipamọ.','Welcome to %s!'=>'Kaabọ si %s!','The plugin is ready for use. If you need some assistance, we can walk you through the basic steps.'=>'Plugin naa ti ṣetan fun lilo. Ti o ba nilo iranlọwọ, a le gbe ọ lọ nipasẹ awọn igbesẹ ipilẹ.','Start the Setup Wizard'=>'Bẹrẹ Wizard Eto','Or click here if you prefer to do it on your own.'=>'Tabi tẹ nibi ti o ba fẹ ṣe e funrararẹ.','Go to the <span class="dashicons dashicons-tag"></span>&nbsp;Tag Groups <a %s>taxonomy settings</a> and <b>select the taxonomy</b> (tag type) of your tags. In most cases just leave the default: Tags (post_tag).'=>'Lọ si <span class="dashicons dashicons-tag"></span>&nbsp;Awọn Ẹgbẹ Tag <a %s>eto taxonomy</a> ki o <b>yan taxonomy</b> (iru tag) ti awọn tag rẹ. Ni ọpọlọpọ awọn ọran, kan fi silẹ aiyipada: Awọn Tag (post_tag).','Go to the tag groups admin page and <b>create some groups</b>.'=>'Lọ si oju-iwe alakoso awọn ẹgbẹ tag ki o <b>da diẹ ninu awọn ẹgbẹ silẹ</b>.','You can find these pages listed on your <a %s>Tag Groups home page</a>.'=>'O le rii awọn oju-iwe wọnyi ti a ṣe akojọ si <a %s>ojúewé ile Awọn Ẹgbẹ Tag</a> rẹ.','Go to your tags and <b>assign them to these groups</b>.'=>'Lọ si awọn tag rẹ ki o <b>pin wọn si awọn ẹgbẹ wọnyi</b>.','Filter by tag group'=>'ṢFilter nipasẹ ẹgbẹ tag','%s created this sample page in the Setup Wizard of the <b>Tag Groups</b> plugin. You can safely edit and delete it or keep it for future reference.'=>'%s ṣẹda oju-iwe ayẹwo yii ninu Setup Wizard ti <b>Awọn Ẹgbẹ Tag</b> amugbooro. O le ṣe atunṣe ati pa a lailewu tabi pa a fun itọkasi ọjọ iwaju.','The following shortcodes use a variety of parameters so that you can get an idea of the options. Feel free to generate a new sample page with more features after upgrading the plugin.'=>'Awọn shortcode ti o tẹle nlo awọn paramita oriṣiriṣi ki o le ni imọran ti awọn aṣayan. Ma ṣe ṣiyemeji lati ṣẹda oju-iwe ayẹwo tuntun pẹlu awọn ẹya diẹ sii lẹhin imudojuiwọn amugbooro naa.','Please find links to the documentation in the <a %s>Tag Groups settings</a>.'=>'Jọwọ wa awọn ọna asopọ si iwe aṣẹ ninu <a %s>eto Awọn Ẹgbẹ Tag</a>.','Tabbed Tag Cloud'=>'Tabi Tag Cloud','Accordion Tag Cloud'=>'Accordion Tag Cloud','Alphabetical Tag Cloud'=>'Alphabetical Tag Cloud','Tag List'=>'Atokọ Tag','Alphabetical Tag Index'=>'Alifabeti Tag Index','The following blocks use a variety of parameters so that you can get an idea of the options. Feel free to generate a new sample page with more features after upgrading the plugin.'=>'Awọn bulọọki ti o tẹle nlo awọn paramita oriṣiriṣi ki o le ni imọran ti awọn aṣayan. Ma ṣe ṣiyemeji lati ṣẹda oju-iwe ayẹwo tuntun pẹlu awọn ẹya diẹ sii lẹhin imudojuiwọn amugbooro naa.','This page was created while you had the Gutenberg editor enabled. Therefore the features only display while Gutenberg is active.'=>'Oju-iwe yii ni a ṣẹda nigba ti o ni olootu Gutenberg ṣiṣẹ. Nitorina awọn ẹya nikan ni a ṣe afihan nigba ti Gutenberg ba jẹ iṣẹ.','Display filter on the "Posts" screen.'=>'Ṣafihan asẹ lori iboju "Posts".','Add a pull-down menu to the filters above the list of posts. If you filter posts by tag groups, then only items will be shown that have tags (terms) in that particular group. This feature can be turned off so that the menu won\'t obstruct your screen if you use a high number of groups. May not work with all taxonomies.'=>'Ṣafikun akojọ aṣayan pull-down si awọn asẹ loke atokọ awọn ifiweranṣẹ. Ti o ba ṣe asẹ awọn ifiweranṣẹ nipasẹ awọn ẹgbẹ tag, lẹhinna awọn ohun kan nikan ni yoo han ti o ni awọn tag (ọrọ) ninu ẹgbẹ yẹn. Ẹya yii le ṣee pa ki akojọ aṣayan naa ma ṣe da iboju rẹ duro ti o ba lo nọmba to ga ti awọn ẹgbẹ. Le ma ṣiṣẹ pẹlu gbogbo taxonomies.','Display filter on the "Tags" screen.'=>'Ṣafihan asẹ lori iboju "Tags".','Add a filter to the list of tags. Disable it here if it conflicts with other plugins or themes.'=>'Ṣafikun asẹ si atokọ awọn tag. Pa a nibi ti o ba ja pẹlu awọn amugbooro tabi awọn akori miiran.','Save Settings'=>'Fipamọ Eto','Gutenberg block preview'=>'Gutenberg block preview','Some blocks can show an approximate preview in the Gutenberg editor. If you deactivate this option, then all blocks will show a static icon with text.'=>'Diẹ ninu awọn bulọọki le fihan awotẹlẹ to sunmọ ni olootu Gutenberg. Ti o ba mu aṣayan yii ṣiṣẹ, lẹhinna gbogbo awọn bulọọki yoo fihan aami alailẹgbẹ pẹlu ọrọ.','Keep groups of translations in sync'=>'Pa awọn ẹgbẹ itumọ pọ','If you activate this option, we try to sync the groups across all language versions of a tag when you save it. Deactivate it to set groups independently.'=>'Ti o ba mu aṣayan yii ṣiṣẹ, a n gbiyanju lati mu awọn ẹgbẹ pọ ni gbogbo awọn ẹya ede ti aami nigbati o ba fipamọ. Mu un ṣiṣẹ lati ṣeto awọn ẹgbẹ lọtọ.','All Tag Groups features are available as Gutenberg blocks. You can also use shortcodes.'=>'Gbogbo awọn ẹya Tag Groups wa gẹgẹ bi awọn bulọọki Gutenberg. O tun le lo shortcode.','Click on the features for more information.'=>'Tẹ lori awọn ẹya fun alaye diẹ sii.','Display the tags in a tabbed tag cloud.'=>'Fihan awọn aami ninu awọ tag ti a pin si awọn taabu.','Example'=>'Apẹẹrẹ','Parameters'=>'Awọn paramita','Please find the parameters in the <a %s>documentation</a>.'=>'Jọwọ wa awọn paramita ninu <a %s>iwe afọwọkọ</a>.','Accordion'=>'Accordion','Display the tags in an accordion.'=>'Fihan awọn aami ninu accordion.','Display the tags in lists under tag groups.'=>'Fihan awọn aami ninu awọn atokọ labẹ awọn ẹgbẹ aami.','Display the tags in tabbed tag cloud with first letters as tabs.'=>'Fihan awọn aami ninu awọ tag ti a pin si awọn taabu pẹlu awọn lẹta akọkọ gẹgẹbi awọn taabu.','(Not tested with right-to-left languages.)'=>'(Ko ti danwo pẹlu awọn ede ti n lọ lati ọtun si osi.)','Display the tags in a list with first letters as heading.'=>'Fihan awọn aami ninu atokọ pẹlu awọn lẹta akọkọ gẹgẹbi akọle.','Group Information'=>'Alaye Ẹgbẹ','Display information about tag groups.'=>'Fihan alaye nipa awọn ẹgbẹ aami.','The function <b>tag_groups_cloud</b> accepts the same parameters as the [tag_groups_cloud] shortcode, except for those that determine tabs and styling.'=>'Iṣẹ <b>tag_groups_cloud</b> gba awọn paramita kanna gẹgẹbi [tag_groups_cloud] shortcode, ayafi fun awọn ti o pinnu awọn taabu ati aṣa.','By default it returns a string with the html for a tabbed tag cloud.'=>'Nipa aiyipada, o n pada okun pẹlu html fun awọ tag ti a pin si awọn taabu.','If the optional second parameter is set to \'true\', the function returns a multidimensional array containing tag groups and tags.'=>'Ti a ba ṣeto paramita keji ti o jẹ aṣayan si \'otitọ\', iṣẹ naa n pada si ṣiṣan oniruuru ti o ni awọn ẹgbẹ tag ati awọn tag.','Enable shortcode in sidebar widgets (if not visible anyway).'=>'Mu shortcode ṣiṣẹ ni awọn widget ẹgbẹ ẹgbẹ (ti ko ba han ni ẹtọ).','Always load shortcode scripts.'=>'Maṣe gbagbe lati gbe awọn iwe afọwọkọ shortcode.','Click for more information'=>'Tẹ lati gba alaye diẹ sii','Turn off to load the scripts only on posts and pages where a shortcode appears.'=>'Pa a silẹ lati gbe awọn iwe afọwọkọ nikan lori awọn ifiweranṣẹ ati awọn oju-iwe nibiti shortcode ba farahan.','Turn on if you use these shortcodes in widgets.'=>'Mu u ṣiṣẹ ti o ba n lo awọn shortcode wọnyi ni awọn widget.','Here you can choose a theme for the Tabbed Tag Cloud and the Accordion Tag Cloud.'=>'Nibi o le yan akori fun Tabbed Tag Cloud ati Accordion Tag Cloud.','New themes can be created with the <a href="http://jqueryui.com/themeroller/" target="_blank">jQuery UI ThemeRoller</a>:'=>'Awọn akori tuntun le ṣẹda pẹlu <a href="http://jqueryui.com/themeroller/" target="_blank">jQuery UI ThemeRoller</a>:','On the page "Theme Roller" you can customize all features or pick one set from the gallery. Finish with the "download" button.'=>'Ninu oju-iwe "Theme Roller" o le ṣe akanṣe gbogbo awọn ẹya tabi yan ọkan seti lati inu ile-ikawe. Pari pẹlu bọtini "download".','On the next page ("Download Builder") you will need to select the version 1.12.x and the components "Widget", "Accordion" and "Tabs". Make sure that before downloading you enter at the bottom as "CSS Scope" <b>.tag-groups-cloud</b> (including the dot).'=>'Ninu oju-iwe ti n bọ ("Download Builder") iwọ yoo nilo lati yan ẹya 1.12.x ati awọn ohun elo "Widget", "Accordion" ati "Tabs". Rii daju pe ki o to ṣe igbasilẹ o tẹ ni isalẹ gẹgẹbi "CSS Scope" <b>.Tag-Groups</b> (pẹlu dot).','Then you unpack the downloaded zip file. You will need the "images" folder and the "jquery-ui.theme.min.css" file.'=>'Lẹhinna o yọkuro faili zip ti a ṣe igbasilẹ. Iwọ yoo nilo folda "images" ati faili "jquery-ui.theme.min.css".','Create a new folder inside your <i>wp-content/uploads</i> folder (for example "my-theme") and copy there these two items.'=>'Ṣẹda folda tuntun laarin folda rẹ <i>wp-content/uploads</i> (fun apẹẹrẹ "my-theme") ki o daakọ awọn ohun meji wọnyi nibẹ.','Enter the name of this new folder (for example "my-theme") below.'=>'Tẹ orukọ folda tuntun yii (fun apẹẹrẹ "my-theme") ni isalẹ.','own theme'=>'akori tirẹ','Don\'t load a theme.'=>'Ma ṣe gbe akori kan.','Here you can turn off jQuery UI themes if your WordPress theme brings its own jQuery UI theme, in order to avoid conflicts.'=>'Nibi o le pa awọn akori jQuery UI ṣiṣẹ ti akori WordPress rẹ ba mu akori jQuery UI tirẹ, lati yago fun awọn ariyanjiyan.','Further options'=>'Awọn aṣayan siwaju','Use jQuery.  (Default is on. Other plugins might override this setting.)'=>'Lo jQuery.  (Aiyipada ni lori. Awọn afikun miiran le ṣe afikun eto yii.)','Tabs triggered by hovering mouse pointer (without clicking).'=>'Tabs ti a fa nipasẹ gbigbe asopọ ẹsẹ (lai tẹ).','Collapsible tabs (toggle open/close).'=>'Awọn taabu ti o le yipada (yi pada ṣi/pa).','HTML in tag description:'=>'HTML ninu apejuwe tag:','By default the description appears in a tooltip when you hover the mouse over a tag in a tag cloud.'=>'Nipa aiyipada apejuwe naa han ninu ifitonileti nigbati o ba foju kọja aami kan ni awọ tag.','If you don\'t trust all users of your site, remove the HTML or use a plugin to give the unfiltered_html capability only to users you trust.'=>'Ti o ko ba ni igbẹkẹle gbogbo awọn olumulo ti aaye rẹ, yọ HTML kuro tabi lo ohun afikun kan lati fun agbara unfiltered_html nikan si awọn olumulo ti o ni igbẹkẹle.','Save Theme Options'=>'Fipamọ Awọn aṣayan Akori','Search for settings'=>'Wa fun awọn eto','Search for setting pages. Type a space to show all settings.'=>'Wa fun awọn oju-iwe eto. Tẹ aaye kan lati fi gbogbo awọn eto han.','Search Results'=>'Awọn Abajade Wiwa','Nothing found'=>'Ko si ohun ti a ri','Active Taxonomies'=>'Awọn Taxonomies Iṣiṣẹ','Group Statistics'=>'Iṣiro Ẹgbẹ','for the selected language'=>'fun ede ti a yan','go to tag group administration'=>'lọ si iṣakoso ẹgbẹ tag','Enable Tag Groups Public API Access'=>'Mu Iwọle API Gbigbasilẹ Tag ṣiṣẹ','Enable public access to tag groups endpoint /wp-json/tag-groups/v1/groups/.'=>'Mu iwọle gbogbogbo si ipari ẹgbẹ tag ṣiṣẹ /wp-json/tag-groups/v1/groups/.','Enable Terms Public API Access'=>'Mu Iwọle API Gbigbasilẹ Awọn Ọrọ ṣiṣẹ','Enable public access to terms endpoint /wp-json/tag-groups/v1/terms/.'=>'Mu iwọle gbogbogbo si ipari awọn ọrọ ṣiṣẹ /wp-json/tag-groups/v1/terms/.','Choose the taxonomies for which you want to use Tag Groups:'=>'Yan awọn taxonomies ti o fẹ lo Tag-Groups fun:','The default texonomy is <b>Tags (post_tag)</b>. Please note that the tag clouds might not work with all taxonomies and that some taxonomies listed here may not be accessible in the admin backend. If you don\'t understand what is going on here, just leave the default.'=>'Taxonomy aiyipada ni <b>Tags (post_tag)</b>. Jọwọ ṣe akiyesi pe awọn awọ tag le ma ṣiṣẹ pẹlu gbogbo awọn taxonomies ati pe diẹ ninu awọn taxonomies ti a darukọ nibi le ma jẹ wiwọle ni abẹ iṣakoso. Ti o ko ba ye ohun ti n ṣẹlẹ nibi, kan fi aiyipada silẹ.','<b>Please deselect taxonomies that you don\'t use. Using several taxonomies for the same post type or hierarchical taxonomies (like categories) is experimental and not supported.</b>'=>'<b>Jọwọ yọkuro awọn taxonomies ti o ko lo. Lilo ọpọlọpọ awọn taxonomies fun iru ifiweranṣẹ kanna tabi awọn taxonomies hierarchical (bii awọn ẹka) jẹ idanwo ati pe ko ni atilẹyin.</b>','To see the post type, hover your mouse over the option.'=>'Lati wo iru ifiweranṣẹ, gbe òrùka rẹ sórí aṣayan náà.','If you use a custom taxonomy, make sure that the attribute "Public" is set to "true" and "Hierarchical" to "false".'=>'Ti o ba n lo taxonomy aṣa, rii daju pe ohun-ini "Public" ti ṣeto si "true" ati "Hierarchical" si "false".','Show hierarchical taxonomies. Not all Tag Groups features will work with these taxonomies.'=>'Fihan taxonomies hierarchical. Kò gbogbo awọn ẹya Tag Groups ni yoo ṣiṣẹ pẹlu awọn taxonomies wọnyi.','Save Taxonomies'=>'Fipamọ Taxonomies','Export'=>'Gbejade','Use this button to export all Tag Groups settings and groups and all terms that are assigned to a group into files.'=>'Lo bọtini yii lati gbejade gbogbo awọn eto Tag Groups ati awọn ẹgbẹ ati gbogbo awọn ọrọ ti a pin si ẹgbẹ sinu awọn faili.','You can import both files separately. Category hierarchy won\'t be saved. When you restore terms that were deleted, they receive new IDs and you must assign them to posts again. Exporting cannot substitute a backup.'=>'O le gbe wọle awọn faili mejeeji ni lọtọ. Ipele ẹka kii yoo wa ni fipamọ. Nigbati o ba mu awọn ọrọ ti a pa, wọn gba awọn ID tuntun ati pe o gbọdọ pin wọn si awọn ifiweranṣẹ lẹẹkansi. Gbejade ko le rọpo afẹyinti.','Export Files'=>'Gbejade Awọn Faili','Import'=>'Gbe wọle','Below you can import previously exported settings/groups or terms from a file.'=>'Ní isalẹ, o le gbe wọle awọn eto/awọn ẹgbẹ tabi awọn ọrọ ti a gbejade tẹlẹ lati faili kan.','It is recommended to back up the database of your site before proceeding.'=>'A ṣe iṣeduro lati ṣe afẹyinti ibi ipamọ data ti aaye rẹ ṣaaju ki o to tẹsiwaju.','Please import the settings before the terms.'=>'Jọwọ gbe wọle awọn eto ṣaaju awọn ọrọ.','Import File'=>'Gbe Faili Wọle','Use this button to delete all tag groups and assignments. Your tags will not be changed. Check the checkbox to confirm.'=>'Lo bọtini yii lati pa gbogbo awọn ẹgbẹ tag ati awọn atunto. Awọn tag rẹ kii yoo yipada. Ṣayẹwo apoti lati jẹrisi.','Please keep in mind that the tag assignments cannot be recovered by the export/import function.'=>'Jọwọ ranti pe awọn atunto tag ko le ṣee gba pada nipasẹ iṣẹ ṣiṣe gbejade/gbe wọle.','I know what I am doing.'=>'Mo mọ ohun ti mo n ṣe.','Delete Groups'=>'Pa Awọn Ẹgbẹ','Delete Settings and Groups'=>'Pa Awọn Eto ati Awọn Ẹgbẹ','Delete all groups and settings when uninstalling the plugin.'=>'Pa gbogbo awọn ẹgbẹ ati awọn eto nigbati o ba yọ plugin naa.','Debug mode is on.'=>'Ẹya amugbooro wa ni ṣiṣi.','Verbose logging is enabled with CM_DEBUG.'=>'Ibi ìkọ́kọ́ àlàyé ti wa ni pẹpẹ pẹlu CM_DEBUG.','Verbose logging is on.'=>'Ibi ìkọ́kọ́ àlàyé wa ni.','Turn off '=>'Pa ','Verbose logging is off.'=>'Ibi ìkọ́kọ́ àlàyé ti wa ni pa.','Turn on'=>'Tan-an','Debug mode is off.'=>'Ipo àyẹ̀wò ti wa ni pa.','Learn more <a %s>about debugging</a>.'=>'Kọ́ ẹ̀kọ́ síi <a %s>nípa àyẹ̀wò</a>.','Migrate tags to the new format of Tag Groups.'=>'Gbe àwọn aami lọ sí fọ́ọ̀mù tuntun ti Ẹgbẹ́ Aami.','The plugin automatically migrates tags to the new format and tries to keep track of changes. There may, however, be cases where other components made unnoticed changes. You might also need to manually migrate tags after you enabled a taxonomy that already contained untracked tags.'=>'Plugin naa n gbe awọn aami lọ si fọ́ọ̀mù tuntun laifọwọyi o si n gbiyanju lati tọpinpin awọn ayipada. Sibẹsibẹ, awọn ọran le wa nibiti awọn eroja miiran ṣe awọn ayipada ti a ko mọ. O tun le nilo lati gbe awọn aami lọ́tọ́ lẹhin ti o ti mu taxonomy ti o ti ni awọn aami ti a ko tọpinpin.','Migrate'=>'Gbe','Running the maintenance can solve issues that you encounter during filtering by tag groups.'=>'Ṣiṣe itọju le yanju awọn iṣoro ti o pade nigba ti o n lọ nipasẹ awọn ẹgbẹ aami.','Maintenance'=>'Itọju','Reset the filter on the tags page to show all tags.'=>'Tun pàtó àlẹmọ naa pada lori oju-iwe awọn aami lati fi gbogbo awọn aami han.','Use it if a JavaScript error disables the filter menu. Note that it is still recommended to find out the cause of the error.'=>'Lo o ti aṣiṣe JavaScript ba pa akojọ àlẹmọ. Ṣe akiyesi pe o tun jẹ imọran pe ki o wa idi ti aṣiṣe naa.','Reset Tag Filter'=>'Tun Àlẹmọ Aami Pada','Please stay on this page until all processes have finished.'=>'Jọwọ duro lori oju-iwe yii titi gbogbo awọn ilana ti pari.','There have been errors.'=>'Iṣoro kan ti ṣẹlẹ.','Continue'=>'Tẹsiwaju','Finished!'=>'Ti pari!','The following terms cannot be used:'=>'Awọn ọrọ ti n bọ ko le ṣee lo:','Number of processed items: '=>'Iye awọn nkan ti a ti ṣiṣẹ: ','Number of changed items: '=>'Iye awọn nkan ti a ti yipada: ','WordPress Version'=>'WordPress Version','Site URL'=>'URL aaye','Home URL'=>'URL ile','Active Theme'=>'Akori ti n ṣiṣẹ','Version'=>'Version','Checking...'=>'N ṣayẹwo...','Show the Response'=>'Fihan Idahun','passed'=>'gun','failed'=>'kuna','Benchmarks'=>'Iwọn','Cache'=>'Cache','Tag groups pro only'=>'Awọn ẹgbẹ Tag pro nikan','Server'=>'Server','Constants'=>'Awọn Constants','Well done!'=>'Seun!','Now go the Tag Group Administration.'=>'Bayi lọ si Isakoso Ẹgbẹ Tag.','Or preview the sample page here.'=>'Tabi wo oju-iwe ayẹwo nibi.','Or go to the <a %1$s>Tag Groups settings</a> or visit the <a %2$s>documentation</a>.'=>'Tabi lọ si <a %1$s>eto Tag Groups</a> tabi ṣabẹwo si <a %2$s>iwe itọnisọna</a>.','Now go to the <a %1$s>Tag Groups settings</a>, or visit the <a %2$s>documentation</a>.'=>'Bayi lọ si <a %1$s>eto Tag Groups</a>, tabi ṣabẹwo si <a %2$s>iwe itọnisọna</a>.','If you need to launch the Setup Wizard again, you can find it in the settings. Just enter "wizard" in the search field.'=>'Ti o ba nilo lati bẹrẹ Setup Wizard lẹẹkansi, o le rii ninu awọn eto. Kan tẹ "wizard" ninu aaye wiwa.','Happy tagging!'=>'Ayọ tagging!','Tag Groups Setup Wizard'=>'Tag Groups Setup Wizard','Now you are ready to create your own tag groups. If you prefer to start out from a sample, we will create for you three groups and three tags. You can play around with them, rename or delete them.'=>'Bayi o ti ṣetan lati ṣẹda awọn ẹgbẹ tag tirẹ. Ti o ba fẹ lati bẹrẹ lati apẹẹrẹ kan, a yoo ṣẹda fun ọ awọn ẹgbẹ mẹta ati awọn tag mẹta. O le ṣere pẹlu wọn, tun lorukọ wọn tabi paarẹ wọn.','Create sample groups:'=>'Ṣẹda awọn ẹgbẹ apẹẹrẹ:','Create sample tags in these groups:'=>'Ṣẹda awọn tag apẹẹrẹ ninu awọn ẹgbẹ wọnyi:','Next Step'=>'Igbesẹ Tẹle','On the following pages we will guide you through the basic settings that you need for the most common features.'=>'Ninu awọn oju-iwe ti n bọ a yoo dari ọ nipasẹ awọn eto ipilẹ ti o nilo fun awọn ẹya ti o wọpọ julọ.','You can later make changes or fine-tune the details in the Tag Groups settings.'=>'O le ṣe awọn ayipada tabi ṣe atunṣe awọn alaye ninu awọn eto Tag Groups nigbamii.','(show me the menu)'=>'(fi mi han akojọ aṣayan)','Feel free to abort the Setup Wizard any time and continue on your own path. You can also launch it again at a later time.'=>'Ma ṣe ṣiyemeji lati fagilee Setup Wizard ni eyikeyi akoko ki o tẹsiwaju lori ọna tirẹ. O tun le bẹrẹ rẹ lẹẹkansi ni akoko miiran.','The wizard will offer more options after upgrading to premium.'=>'Wizard naa yoo funni ni diẹ sii awọn aṣayan lẹhin ti o ba ṣe igbesoke si premium.','Choose the taxonomies for which you want to use tag groups.'=>'Yan awọn taxonomies ti o fẹ lati lo awọn ẹgbẹ tag fun.','In most cases the default taxonomy <b>Tags (post_tag)</b> will do the job.'=>'Ninu ọpọlọpọ awọn ọran, taxonomy aiyipada <b>Tags (post_tag)</b> yoo ṣe iṣẹ naa.','post type'=>'post type','You will find more options in the Tag Groups settings.'=>'Iwọ yoo rii diẹ sii awọn aṣayan ninu awọn eto Tag Groups.','Tag Group Administration'=>'Iṣakoso Ẹgbẹ Tag','Filter by label'=>'Ṣafihan nipasẹ aami','Tag Group name'=>'Orukọ Ẹgbẹ Tag','Number of assigned tags'=>'Iye awọn aami ti a ti yan','Actions'=>'Iṣe','Change order'=>'Yipada aṣẹ','Group ID'=>'ID ẹgbẹ','Edit'=>'Ṣatunkọ','Create'=>'Ṣẹda','new'=>'titun','label'=>'ami','Delete this group.'=>'Pa ẹgbẹ yii run.','Create a new group below.'=>'Ṣẹda ẹgbẹ tuntun ni isalẹ.','Add New Tag Group'=>'Fikun un Ẹgbẹ Aami Tuntun','move up'=>'gbe soke','move down'=>'gbe silẹ','reload'=>'tun kọ','next page'=>'iwe-iwe ti n bọ','previous page'=>'iwe-iwe ti tẹlẹ','go to page:'=>'lọ si iwe-iwe:','Show posts'=>'Fihan awọn ifiweranṣẹ','Show tags'=>'Fihan awọn aami','Do you really want to delete this tag group?'=>'Ṣe o dajudaju fẹ pa ẹgbẹ aami yii run?','Please visit <a %1$s>%2$s</a>.'=>'Jọwọ ṣabẹwo si <a %1$s>%2$s</a>.','Read more'=>'Ka siwaju','Thanks for using Tag Groups | %1$sTaxoPress.com%2$s | Version %3$s'=>'O ṣeun fun lilo Tag Groups | %1$sTaxoPress.com%2$s | Version %3$s','Assign to'=>'Yàn si','Filter off'=>'Ifilọlẹ pa','Please select one of the languages above to see the correct tag groups!'=>'Jọwọ yan ọkan ninu awọn ede loke lati wo awọn ẹgbẹ aami to tọ!','Groups'=>'Ẹgbẹ']];